// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type MailToPasswordProps = Record<string, any>;

const LockIcon = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect>
    <path d="M7 11V7a5 5 0 0 1 10 0v4"></path>
  </svg>
);

const EyeIcon: React.FC<{ progress: number }> = ({ progress }) => {
  const lineLength = 32;
  const strokeDashoffset = interpolate(progress, [0, 1], [lineLength, 0]);

  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
      <circle cx="12" cy="12" r="3"></circle>
      {progress > 0 && (
        <line
          x1="2" y1="2" x2="22" y2="22"
          strokeDasharray={lineLength}
          strokeDashoffset={strokeDashoffset}
        />
      )}
    </svg>
  );
};

const MailToPassword: React.FC<MailToPasswordProps> = ({
  backgroundColor = "#f1f5f9",
  transparentBackground = false,
  durationInSeconds = 8,
  recipientName = "Malloy Studio",
  addressText = "123 Secure Ln.",
  passwordText = "123SecureLn.",
  highlightColor = "#fde047",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Springs ---
  const envEnter = spring({ frame: frame - 15, fps, config: { damping: 14 } });
  const highlight = spring({ frame: frame - 70, fps, config: { damping: 17 } }); // Delayed by 0.5s
  const morph = spring({ frame: frame - 110, fps, config: { damping: 15 } });
  const textCrossfade = spring({ frame: frame - 135, fps, config: { damping: 16 } });

  // --- Calculations ---
  // Base Entrance (Slide & Tilt)
  const groupY = interpolate(envEnter, [0, 1], [1080, 0]);
  const groupRotate = interpolate(envEnter, [0, 1], [-8, 0]);

  // Envelope Morph Out
  const envDropY = interpolate(morph, [0, 1], [0, 800]);
  const envDropRotate = interpolate(morph, [0, 1], [0, 12]);
  const envOpacity = interpolate(morph, [0, 0.4], [1, 0], { extrapolateRight: "clamp" });

  // Address Alignment (Moves from envelope position to absolute center)
  // Adjusted start position to center the text better on the envelope
  const addressLeft = interpolate(morph, [0, 1], [900, 960]);
  const addressTop = interpolate(morph, [0, 1], [585, 540]);
  const addressTranslateX = interpolate(morph, [0, 1], [0, -50]);
  const highlightOpacity = interpolate(morph, [0, 0.5], [1, 0], { extrapolateRight: "clamp" });

  // Password Input Bar Reveal
  const passBoxOpacity = interpolate(morph, [0.4, 1], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const passBoxScale = interpolate(morph, [0.4, 1], [0.8, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const passBoxWidth = interpolate(morph, [0.4, 1], [300, 520], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Text Opacity
  const plainPassOpacity = interpolate(textCrossfade, [0, 1], [0, 1]);

  // Password Typing Effect
  const typingStartFrame = 140;
  const typingDuration = passwordText.length * 3; // 3 frames per character
  const typingProgress = interpolate(
    frame,
    [typingStartFrame, typingStartFrame + typingDuration],
    [0, passwordText.length],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const charsToShow = Math.floor(typingProgress);
  const typedPassword = passwordText.slice(0, charsToShow);
  const isTyping = frame >= typingStartFrame && charsToShow < passwordText.length;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <AbsoluteFill
        style={{
          transform: `translateY(${groupY}px) rotate(${groupRotate}deg)`,
          transformOrigin: "50% 50%",
        }}
      >
        
        {/* ENVELOPE */}
        <div
          style={{
            position: "absolute",
            width: 800,
            height: 350,
            left: 960 - 400, // 560
            top: 540 - 175,  // 365
            backgroundColor: "#ffffff",
            borderRadius: 12,
            boxShadow: "0 25px 50px -12px rgba(0,0,0,0.15)",
            transform: `translateY(${envDropY}px) rotate(${envDropRotate}deg)`,
            opacity: envOpacity,
          }}
        >
          {/* Stamp */}
          <div style={{ position: "absolute", right: 30, top: 30, width: 65, height: 80, backgroundColor: "#cbd5e1", borderRadius: 6, display: "flex", flexWrap: "wrap", padding: 6, gap: 4 }}>
             <div style={{ width: "100%", height: 40, backgroundColor: "#94a3b8", borderRadius: 4, opacity: 0.5 }} />
          </div>
          
          {/* Postmark Circles */}
          <div style={{ position: "absolute", right: 60, top: 60, width: 55, height: 55, border: "2px solid #e2e8f0", borderRadius: "50%", opacity: 0.8 }} />
          <div style={{ position: "absolute", right: 80, top: 45, width: 40, height: 40, border: "1px solid #e2e8f0", borderRadius: "50%", opacity: 0.6 }} />

          {/* Return Address Lines */}
          <div style={{ position: "absolute", left: 40, top: 40, width: 140, height: 12, backgroundColor: "#e2e8f0", borderRadius: 6 }} />
          <div style={{ position: "absolute", left: 40, top: 64, width: 100, height: 12, backgroundColor: "#e2e8f0", borderRadius: 6 }} />
          <div style={{ position: "absolute", left: 40, top: 88, width: 60, height: 12, backgroundColor: "#e2e8f0", borderRadius: 6 }} />

          {/* Fixed Recipient Name on Envelope */}
          <div
            style={{
              position: "absolute",
              left: 340, // Centered further left
              top: 120, // Moved up to create more vertical space
              fontSize: 28,
              fontWeight: 600,
              color: "#334155",
            }}
          >
            {recipientName}
          </div>
        </div>

        {/* ADDRESS TEXT & PASSWORD BAR CONTAINER */}
        <div
          style={{
            position: "absolute",
            left: addressLeft,
            top: addressTop,
            transform: `translate(${addressTranslateX}%, -50%)`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {/* Password Input Background & Border */}
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              transform: `translate(-50%, -50%) scale(${passBoxScale})`,
              width: passBoxWidth,
              height: 84,
              backgroundColor: "#ffffff",
              border: "2px solid #cbd5e1",
              borderRadius: 16,
              opacity: passBoxOpacity,
              boxShadow: "0 10px 30px rgba(0,0,0,0.08)",
              zIndex: -2,
            }}
          >
            {/* Input Icons */}
            <div style={{ position: "absolute", left: 24, top: "50%", transform: "translateY(-50%)" }}>
              <LockIcon />
            </div>
            <div style={{ position: "absolute", right: 24, top: "50%", transform: "translateY(-50%)" }}>
              <EyeIcon progress={0} />
            </div>
          </div>

          {/* Text Elements Wrapper */}
          <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center" }}>
            
            {/* Yellow Highlight Backing */}
            <div
              style={{
                position: "absolute",
                left: -12,
                top: -4,
                bottom: -4,
                width: `calc(${interpolate(highlight, [0, 1], [0, 100])}% + 24px)`,
                backgroundColor: highlightColor,
                borderRadius: 6,
                zIndex: -1,
                opacity: highlightOpacity,
                transform: "rotate(-1deg)",
              }}
            />

            {/* Layer 1: Address Plain Text (Envelope Font) */}
            <div
              style={{
                fontSize: 32,
                fontWeight: 500,
                color: "#0f172a",
                opacity: interpolate(textCrossfade, [0, 1], [1, 0]),
                whiteSpace: "nowrap",
              }}
            >
              {addressText}
            </div>

            {/* Layer 2: Password Plain Text (Input Font) with Typing Effect */}
            <div
              style={{
                position: "absolute",
                left: "50%",
                top: "50%",
                transform: "translate(-50%, -50%)",
                display: "flex",
                alignItems: "center",
                opacity: plainPassOpacity,
              }}
            >
              <div style={{ position: "relative" }}>
                {/* Invisible Spacer to maintain centered layout while typing */}
                <div style={{ display: "flex", alignItems: "center", opacity: 0, pointerEvents: "none" }}>
                  <span
                    style={{
                      fontSize: 28,
                      fontFamily: robotoMonoFamily,
                      whiteSpace: "nowrap",
                      transform: "translateY(2px)",
                    }}
                  >
                    {passwordText}
                  </span>
                  <div style={{ width: 3, height: 34, marginLeft: 10 }} />
                </div>
                
                {/* Visible Typing Content */}
                <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, display: "flex", alignItems: "center" }}>
                  <span
                    style={{
                      fontSize: 28,
                      fontFamily: robotoMonoFamily,
                      color: "#0f172a",
                      whiteSpace: "nowrap",
                      transform: "translateY(2px)",
                    }}
                  >
                    {typedPassword}
                  </span>
                  
                  {/* Blinking Cursor for Plain Text */}
                  {textCrossfade > 0.8 && (
                    <div
                      style={{
                        width: 3,
                        height: 34,
                        backgroundColor: "#0f172a",
                        marginLeft: 10,
                        opacity: isTyping ? 1 : (Math.floor(frame / 15) % 2 === 0 ? 1 : 0),
                      }}
                    />
                  )}
                </div>
              </div>
            </div>

          </div>
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default MailToPassword;